export function getCommunesTotal(slug: string): number {
  return (COMMUNES_PAR_DEPARTEMENT[slug] || []).reduce((n, g) => n + g.communes.length, 0)
}

export function getCommunesGrandTotal(): number {
  return Object.keys(COMMUNES_PAR_DEPARTEMENT).reduce((n, slug) => n + getCommunesTotal(slug), 0)
}
